Single file, Express 5, one dependency beyond Express (`express-session`); hashing uses stdlib `crypto.scrypt`. Not executed here.

```js
// app.js — npm i express express-session
const express = require('express');
const session = require('express-session');
const crypto = require('node:crypto');
const { promisify } = require('node:util');

const scrypt = promisify(crypto.scrypt);
const prod = process.env.NODE_ENV === 'production';
if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET required');

const app = express();
// app.set('trust proxy', 1); // required behind a reverse proxy, or req.ip is the proxy's IP
app.use(express.json());
app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax', secure: prod, maxAge: 8 * 60 * 60 * 1000 },
  // chisle: default MemoryStore; use connect-redis or similar in production
}));

// --- password hashing ---
async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return crypto.timingSafeEqual(key, await scrypt(password, salt, 64));
}

// Verified against when the user doesn't exist, so response time doesn't reveal valid usernames
const dummyHash = hashPassword(crypto.randomBytes(16).toString('hex'));

// --- rate limiting of failed attempts ---
// chisle: in-memory fixed window; move to Redis when running more than one process
const MAX_FAILS = 5;
const WINDOW_MS = 15 * 60 * 1000;
const attempts = new Map(); // key -> { count, resetAt }

// Counts the attempt up front (before the async hash) so parallel requests can't slip past the limit.
// Returns ms until unblocked, or 0 if allowed.
function hit(key) {
  const now = Date.now();
  let a = attempts.get(key);
  if (!a || a.resetAt <= now) attempts.set(key, (a = { count: 0, resetAt: now + WINDOW_MS }));
  a.count++;
  return a.count > MAX_FAILS ? a.resetAt - now : 0;
}

// Successful logins don't count; decrement rather than reset so one valid login can't clear an IP's failures
function unhit(key) {
  const a = attempts.get(key);
  if (a) a.count--;
}

setInterval(() => {
  const now = Date.now();
  for (const [k, a] of attempts) if (a.resetAt <= now) attempts.delete(k);
}, WINDOW_MS).unref();

// --- users ---
const users = new Map(); // chisle: in-memory; replace with your DB. username -> { id, username, hash }

function parseCredentials(body) {
  const { username, password } = body ?? {};
  if (typeof username !== 'string' || typeof password !== 'string') return null;
  if (!username || username.length > 64 || password.length < 8 || password.length > 1024) return null;
  return { username: username.toLowerCase(), password };
}

// --- routes ---
app.post('/register', async (req, res) => {
  const creds = parseCredentials(req.body);
  if (!creds) return res.status(400).json({ error: 'Invalid username or password' });
  if (users.has(creds.username)) return res.status(409).json({ error: 'Username taken' });
  users.set(creds.username, {
    id: crypto.randomUUID(),
    username: creds.username,
    hash: await hashPassword(creds.password),
  });
  res.status(201).json({ ok: true });
});

app.post('/login', async (req, res, next) => {
  const creds = parseCredentials(req.body);
  if (!creds) return res.status(400).json({ error: 'Invalid username or password' });

  const keys = [`ip:${req.ip}`, `user:${creds.username}`];
  const wait = Math.max(...keys.map(hit));
  if (wait) {
    return res.set('Retry-After', String(Math.ceil(wait / 1000)))
      .status(429).json({ error: 'Too many attempts, try again later' });
  }

  const user = users.get(creds.username);
  const match = await verifyPassword(creds.password, user?.hash ?? (await dummyHash));
  if (!user || !match) return res.status(401).json({ error: 'Invalid username or password' });

  keys.forEach(unhit);
  // New session ID on login prevents session fixation
  req.session.regenerate((err) => {
    if (err) return next(err);
    req.session.userId = user.id;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid').json({ ok: true });
  });
});

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.get('/me', requireAuth, (req, res) => res.json({ userId: req.session.userId }));

app.listen(3000);
```

Check, after registering `alice`: attempts 1–5 should print 401, then 429.

```sh
for i in $(seq 7); do curl -s -o /dev/null -w '%{http_code}\n' -H 'content-type: application/json' \
  -d '{"username":"alice","password":"wrongpass"}' localhost:3000/login; done
```

Things to know before using this:

- **Account lockout:** limiting per username means anyone can lock a known account out for 15 minutes by sending five bad passwords. Dropping the `user:` key removes that, but then a distributed attack on one account is only limited per IP.
- **Single process only:** sessions, the attempt counters and users all live in memory, so they vanish on restart and aren't shared across instances.
- **Express 4:** the async handlers rely on Express 5 forwarding rejected promises; on Express 4, wrap them in try/catch and call `next(err)`.

